/**
 * Deterministic exact linear algebra, per Brief §16 ("exact/fraction-free
 * matrix solving for temporary calculation") and the Phase-0 build list's
 * "fraction-free linear algebra" item (§33).
 *
 * A NOTE ON "FRACTION-FREE": Bareiss's algorithm exists to let integer-only
 * Gaussian elimination stay exact without fractions ever appearing, by
 * using a division that is provably always exact at each step. CharacterLab
 * already has an exact rational type (kernel/rational.ts) with automatic
 * GCD reduction on every operation, which solves the same underlying
 * problem — "no imprecision, no unbounded intermediate growth" — by a
 * different, and for this codebase more natural, route: every Rational is
 * kept in lowest terms at all times, so intermediate values in elimination
 * cannot grow the way ungreduced integer fractions would. What matters for
 * Brief §3.1/§32 — no floating point, no unspecified rounding, a fully
 * exact and reproducible result — holds equally either way. This module
 * documents that choice explicitly rather than silently departing from the
 * brief's wording.
 *
 * Determinism requires a FIXED pivot rule and CANONICAL row/column order
 * (§6, §32). Row/column order here is whatever order the caller's index
 * array is in — callers (kernel/activation.ts) pass concepts pre-sorted by
 * canonical ConceptKey (kernel/canonical.ts), so index order IS canonical
 * order; this module never reorders anything on its own. The pivot rule is
 * fixed and stated below.
 */

import { Rational } from './rational';

export type Matrix = readonly (readonly Rational[])[];
export type Vec = readonly Rational[];

export interface SolveResult {
  readonly solution: Rational[];
}

export class SingularMatrixError extends Error {
  constructor(readonly pivotColumn: number) {
    super(`Matrix is singular (or numerically so): no nonzero pivot available for column ${pivotColumn}`);
  }
}

function cloneMatrix(A: Matrix): Rational[][] {
  return A.map((row) => [...row]);
}

/**
 * Solve Ax = b exactly for square A, via Gaussian elimination with partial
 * pivoting.
 *
 * Pivot rule (fixed, per §32's determinism requirement): at column k, if
 * A[k][k] is zero, scan rows k+1..n-1 IN INCREASING INDEX ORDER for the
 * first row with a nonzero entry in column k and swap it into place. If no
 * such row exists, the matrix is singular at that column — this is the
 * "defined singularity behavior" §18 asks for: callers get a typed
 * SingularMatrixError naming the column, never a silent NaN/Infinity.
 *
 * This is plain Gaussian elimination, not literal row-echelon-by-minors
 * Bareiss — see the module comment for why that is the right choice given
 * kernel/rational.ts's exact, auto-reduced representation.
 */
export function solveLinearSystem(A: Matrix, b: Vec): SolveResult {
  const n = A.length;
  if (n === 0) return { solution: [] };
  for (const row of A) {
    if (row.length !== n) throw new RangeError('solveLinearSystem: A must be square');
  }
  if (b.length !== n) throw new RangeError('solveLinearSystem: b length must match A');

  // Augmented matrix [A | b], exact Rational entries throughout.
  const M: Rational[][] = cloneMatrix(A).map((row, i) => [...row, b[i]]);

  for (let k = 0; k < n; k++) {
    if (M[k][k].isZero()) {
      let swapRow = -1;
      for (let r = k + 1; r < n; r++) {
        if (!M[r][k].isZero()) {
          swapRow = r;
          break;
        }
      }
      if (swapRow === -1) throw new SingularMatrixError(k);
      const tmp = M[k];
      M[k] = M[swapRow];
      M[swapRow] = tmp;
    }
    const pivot = M[k][k];
    for (let r = k + 1; r < n; r++) {
      if (M[r][k].isZero()) continue;
      const factor = M[r][k].div(pivot);
      for (let c = k; c <= n; c++) {
        M[r][c] = M[r][c].sub(factor.mul(M[k][c]));
      }
    }
  }

  // Back-substitution.
  const x = new Array<Rational>(n);
  for (let i = n - 1; i >= 0; i--) {
    let acc = M[i][n];
    for (let j = i + 1; j < n; j++) {
      acc = acc.sub(M[i][j].mul(x[j]));
    }
    x[i] = acc.div(M[i][i]);
  }
  return { solution: x };

/** A·x — used by tests to confirm a solution actually satisfies the system
 * it was solved from (§32-style "prove it," not "assert it"). */
export function matVecMul(A: Matrix, x: Vec): Rational[] {
  return A.map((row) => row.reduce((acc, a_ij, j) => acc.add(a_ij.mul(x[j])), Rational.ZERO));
}

export function identity(n: number): Rational[][] {
  return Array.from({ length: n }, (_, i) =>
    Array.from({ length: n }, (_, j) => (i === j ? Rational.ONE : Rational.ZERO)),
  );
}

/** a·b = Σ a_i·b_i — Phase 2.9's trait-projection quadratic form is built
 * entirely from this and `matVecMul`, already present in this file. */
export function dot(a: Vec, b: Vec): Rational {
  if (a.length !== b.length) throw new RangeError('dot: vectors must have the same length');
  return a.reduce((acc, ai, i) => acc.add(ai.mul(b[i])), Rational.ZERO);
}

/**
 * b + w^T·x + x^T·Q·x — the trait/personality-style bounded quadratic
 * projection form the master Brief §9.1 specifies for named-trait
 * projections (`T_k(P) = g(b_k + w_k^T·P + P^T·Q_k·P)`) and Phase 2.9's
 * Brief §21 reuses verbatim for named Acquired Identity Traits over the
 * IdentityStrength vector instead of the personality vector P. Kept here
 * rather than in a Phase-2.9-specific module so Phase 3 (latent
 * personality) can reuse it without re-deriving the same three-term form.
 * Callers apply `Rational.boundedResponse` to the result themselves — this
 * function returns the raw (possibly unbounded) quadratic value.
 */
export function quadraticForm(b: Rational, w: Vec, Q: Matrix, x: Vec): Rational {
  return b.add(dot(w, x)).add(dot(x, matVecMul(Q, x)));
}

/**
 * Spreading activation, per Brief §16.
 *
 *   a = b + βWa  =>  a = (I - βW)^-1 b
 *
 * Uniqueness: since W is row-substochastic (Σ_j W_ij ≤ 1), ‖W‖_∞ ≤ 1, so
 * ‖βW‖_∞ ≤ β < 1 and ρ(βW) < 1 — (I - βW) is invertible and the solution
 * is unique (Brief §32 "Activation uniqueness"). This module additionally
 * proves (see kernel/linalg.ts's SingularMatrixError path and
 * test/activation.test.ts) that (I - βW) is in fact strictly diagonally
 * dominant whenever W is row-substochastic and 0 ≤ β < 1 — which means
 * Gaussian elimination WITHOUT row-swapping never hits a zero pivot for
 * any graph state this module can ever produce. That's a stronger,
 * checkable fact worth recording: activation solving on a legally-mutated
 * AssociationGraph should never throw SingularMatrixError in practice; if
 * it ever does, that's evidence the row-substochastic invariant was
 * violated somewhere upstream, not a normal degenerate case to catch and
 * ignore.
 */

import { Rational } from '../kernel/rational';
import { ConceptKey } from '../kernel/canonical';
import { quantize, D } from '../kernel/lattice';
import { solveLinearSystem, identity, Matrix } from '../kernel/linalg';
import { AssociationGraph, getWeight } from './associations';

export type ActivationVector = ReadonlyMap<ConceptKey, Rational>;

export interface ActivationParams {
  /** β ∈ [0, 1) — spreading decay per hop (Brief §16). */
  readonly beta: Rational;
  /** θ_A — accessibility threshold an Action's own concept must clear to
   * be a candidate (§22.2). */
  readonly thetaA: Rational;
  /** K_A — max candidates surviving accessibility filtering (§22.3). */
  readonly kA: number;
}

function toDenseW(graph: AssociationGraph): Matrix {
  return graph.concepts.map((i) => graph.concepts.map((j) => getWeight(graph, i, j)));
}

function toDenseB(graph: AssociationGraph, base: ActivationVector): Rational[] {
  return graph.concepts.map((c) => base.get(c) ?? Rational.ZERO);
}

/**
 * Solve a = (I - βW)^-1 b over the graph's fixed concept universe, then
 * quantize each entry onto the lattice at commit (§5.2, §6). Returns a
 * dense map covering every concept in the universe (0 where nothing
 * spreads to it), so callers never have to special-case "concept never
 * seen."
 */
export function solveActivation(graph: AssociationGraph, beta: Rational, base: ActivationVector): ActivationVector {
  if (beta.isNegative() || !beta.lt(Rational.ONE)) {
    throw new RangeError('solveActivation: beta must satisfy 0 <= beta < 1');
  }
  const n = graph.concepts.length;
  if (n === 0) return new Map();

  const W = toDenseW(graph);
  const I = identity(n);
  const A: Rational[][] = I.map((row, i) => row.map((val, j) => val.sub(beta.mul(W[i][j]))));
  const b = toDenseB(graph, base);

  const { solution } = solveLinearSystem(A, b);

  const result = new Map<ConceptKey, Rational>();
  solution.forEach((x, idx) => {
    const { value } = quantize(x, D);
    result.set(graph.concepts[idx], value);
  });
  return result;
}

/** encoding-access-math/0.1-candidate. Pure comparison kernels, never public ingress or state writers. */
import {ExactRational as Q,roundEven} from '../substrate/exactMath';
const zero=Object.freeze(Q.of(0n)),one=Object.freeze(Q.of(1n));
const fail=(why:string):never=>{throw new RangeError('encoding-access math: '+why);};
function nonnegative(q:Q):Q {if(!(q instanceof Q)||typeof q.numerator!=='bigint'||typeof q.denominator!=='bigint'||q.denominator<=0n||q.numerator<0n)fail('nonnegative rational');return Q.of(q.numerator,q.denominator);}
function unit(q:Q):Q {const v=nonnegative(q);if(v.compare(one)>0)fail('unit interval');return v;}
const sum=(xs:readonly Q[])=>xs.reduce((a,b)=>a.add(b),zero);
const max=(a:Q,b:Q)=>a.compare(b)>=0?a:b;
function count(n:number,max=32){if(!Number.isInteger(n)||n<0||n>max)fail('bounded count');}
function dense(xs:readonly unknown[]){if(!Array.isArray(xs)||Object.getPrototypeOf(xs)!==Array.prototype)fail('plain dense array');const ds=Object.getOwnPropertyDescriptors(xs);if(Reflect.ownKeys(ds).some(k=>k!=='length'&&(typeof k!=='string'||!/^(0|[1-9][0-9]*)$/.test(k)))||Object.values(ds).some(d=>!('value'in d))||Object.keys(ds).length!==xs.length+1)fail('plain dense array');}
function keys(xs:readonly string[]){dense(xs);count(xs.length);if(xs.some(k=>typeof k!=='string'||!k||k!==k.normalize('NFC'))||new Set(xs).size!==xs.length)fail('distinct nonempty NFC keys');}
function compareKeys(a:string,b:string){const encoder=new TextEncoder(),x=encoder.encode(a),y=encoder.encode(b);for(let i=0;i<Math.min(x.length,y.length);i++)if(x[i]!==y[i])return x[i]-y[i];return x.length-y.length;}

 return values.map((x,i)=>important[i]?committed[i]:denom.numerator?x.divide(denom):zero);
}
function graph(labels:readonly string[],w:readonly (readonly Q[])[],scale?:bigint){keys(labels);dense(w);w.forEach(dense);if(w.length!==labels.length||w.some(row=>row.length!==labels.length))fail('graph dimensions');if(scale!==undefined&&(typeof scale!=='bigint'||scale<=0n))fail('scale');
 return w.map((row,i)=>{const values=row.map((x,j)=>{const value=unit(x);if(i===j&&value.numerator)fail('self edge');if(scale!==undefined&&(value.numerator*scale)%value.denominator)fail('off-lattice state');return value;});if(sum(values).compare(one)>0)fail('row mass');return values;});
}
export function associationCandidate(labels:readonly string[],prior:readonly (readonly Q[])[],activation:readonly Q[],p:{scale:bigint;eta:Q;lambda:Q;elapsed:Q}) {
 const w=graph(labels,prior,p.scale);dense(activation);if(activation.length!==labels.length)fail('coactivation dimension');const z=activation.map(unit),decay=one.divide(one.add(nonnegative(p.lambda).multiply(nonnegative(p.elapsed)))),eta=nonnegative(p.eta);
 const rows=w.map((row,i)=>{const exact=row.map((value,j)=>i===j?zero:value.multiply(decay).add(eta.multiply(z[i]).multiply(z[j]))),quantized=exact.map(x=>roundEven(x.numerator*p.scale,x.denominator)),total=quantized.reduce((a,b)=>a+b,0n);let mass=quantized.slice();
  if(total>p.scale){const allocations=quantized.map((q,j)=>({j,mass:q*p.scale/total,remainder:q*p.scale%total}));let left=p.scale-allocations.reduce((a,b)=>a+b.mass,0n);const ranked=[...allocations].sort((a,b)=>a.remainder!==b.remainder?a.remainder>b.remainder?-1:1:compareKeys(labels[a.j],labels[b.j]));for(const a of ranked){if(left===0n)break;a.mass++;left--;}if(left)fail('remainder conservation');mass=allocations.map(a=>a.mass);}
  return {exact,quantized,mass,overflow:total>p.scale,values:mass.map(n=>Q.of(n,p.scale))};
 });return {rows,values:rows.map(row=>row.values)};
}
export function spreadingActivation(labels:readonly string[],weights:readonly (readonly Q[])[],base:readonly Q[],beta:Q,scale:bigint){
 const w=graph(labels,weights);unit(beta);if(beta.compare(one)>=0)fail('beta must be below one');if(typeof scale!=='bigint'||scale<=0n)fail('scale');dense(base);if(base.length!==labels.length)fail('activation dimension');const b=base.map(nonnegative),n=labels.length;
 const a=w.map((row,i)=>row.map((x,j)=>(i===j?one:zero).subtract(beta.multiply(x))));
 for(let k=0;k<n;k++){if(a[k][k].numerator===0n)fail('unexpected zero pivot');for(let i=k+1;i<n;i++){const factor=a[i][k].divide(a[k][k]);for(let j=k;j<n;j++)a[i][j]=a[i][j].subtract(factor.multiply(a[k][j]));b[i]=b[i].subtract(factor.multiply(b[k]));}}
 const exact=Array.from({length:n},()=>zero);for(let i=n-1;i>=0;i--){let rhs=b[i];for(let j=i+1;j<n;j++)rhs=rhs.subtract(a[i][j].multiply(exact[j]));exact[i]=nonnegative(rhs.divide(a[i][i]));}
 return {exact,quantized:exact.map(x=>Q.of(roundEven(x.numerator*scale,x.denominator),scale))};
}

/** direct-associative-access-component/0.1-candidate: exact reference factorization, no public cue authority. */
import {ExactRational as Q,roundEven} from '../substrate/exactMath';
import {canonicalEncode,text} from '../substrate/canonicalEncoding';
import {spreadingActivation} from './encodingAccessMath';
const zero=Object.freeze(Q.of(0n));
const fail=(why:string):never=>{throw new RangeError('direct associative access: '+why);};
function keys(xs:readonly string[]){if(!Array.isArray(xs)||Object.getPrototypeOf(xs)!==Array.prototype||xs.length>32||Array.from({length:xs.length},(_,i)=>Object.hasOwn(xs,i)).some(x=>!x)||new Set(xs).size!==xs.length)fail('key set');for(const k of xs)if(typeof k!=='string'||!k||k!==k.normalize('NFC'))fail('key');}
function nonnegative(q:Q){if(!(q instanceof Q)||typeof q.numerator!=='bigint'||typeof q.denominator!=='bigint'||q.denominator<=0n||q.numerator<0n)fail('cue domain');return Object.freeze(Q.of(q.numerator,q.denominator));}
const compare=(x:string,y:string)=>{const a=canonicalEncode(text(x)),b=canonicalEncode(text(y));for(let i=0;i<Math.min(a.length,b.length);i++)if(a[i]!==b[i])return a[i]-b[i];return a.length-b.length;};
export function composeDirectAssociativeAccess(retained:readonly string[],graphKeys:readonly string[],weights:readonly (readonly Q[])[],cues:ReadonlyMap<string,Q>,beta:Q,scale:bigint){
 keys(retained);keys(graphKeys);keys([...cues.keys()]);const currentCue=new Map([...cues].map(([k,v])=>[k,nonnegative(v)]));
 const union=[...new Set([...retained,...graphKeys])].sort(compare);keys(union);
 const b=graphKeys.map(k=>currentCue.get(k)??zero),solved=spreadingActivation(graphKeys,weights,b,beta,scale),indices=new Map(graphKeys.map((k,i)=>[k,i])),episodic=new Set(retained);
 const rows=union.map(key=>{
  const i=indices.get(key),cueSeed=currentCue.get(key)??zero,directMatch=episodic.has(key)?cueSeed:zero;
  const learnedSpread=i===undefined?zero:solved.exact[i].subtract(b[i]);if(learnedSpread.numerator<0n)fail('negative learned spread');
  const contribution=directMatch.add(learnedSpread),quantized=Q.of(roundEven(contribution.numerator*scale,contribution.denominator),scale);
  return Object.freeze({key,episodic:episodic.has(key),graph:i!==undefined,cueSeed,directMatch,learnedSpread:Object.freeze(learnedSpread),contribution:Object.freeze(contribution),quantized:Object.freeze(quantized)});
 });
 return Object.freeze(rows);
}

/** canonical-event-recall-component/0.1-candidate; supplied authenticated reads/cue. */
import {ExactRational as Q} from '../substrate/exactMath';
import {unsigned,type CanonicalValue} from '../substrate/canonicalEncoding';
import {canonicalOperationKeyIndex} from './canonicalChildKeys';
import {fragmentRetainedUnits} from './retentionFragmentation';
import {composeDirectAssociativeAccess} from './directAssociativeAccess';
import {rankAccessibleEpisodes} from './encodingAccessMath';
export interface CanonicalEventAcquisition {readonly id:bigint;readonly acquiredAt:bigint;readonly units:readonly {readonly key:CanonicalValue;readonly views:readonly Uint8Array[]}[]}
export interface CanonicalEventRecallInput {
 readonly cue:{readonly kind:'Absent'}|{readonly kind:'Present';readonly key:CanonicalValue};
 readonly memory:readonly CanonicalEventAcquisition[];
 readonly graph:{readonly keys:readonly CanonicalValue[];readonly weights:readonly (readonly Q[])[]};
 readonly presentations:ReadonlyMap<bigint,readonly bigint[]>;
 readonly now:bigint;
 readonly calibration:{readonly beta:Q;readonly scale:bigint;readonly lambda:Q;readonly exponent:number;readonly omegaB:Q;readonly omegaA:Q;readonly k:number};
}
export function recallCanonicalEventAcquisitions(input:CanonicalEventRecallInput){
 const p=input.calibration;
 rankAccessibleEpisodes([],new Map(),input.now,p);composeDirectAssociativeAccess([],[],[],new Map(),p.beta,p.scale);
 if(input.cue.kind==='Absent')return {disposition:'UnavailableCue' as const,access:[],scores:[],recalled:[]};
 if(input.cue.kind!=='Present')throw Error('CANONICAL_EVENT_CUE');
 if(!Array.isArray(input.memory)||input.memory.length>32||Array.from({length:input.memory.length},(_,i)=>!Object.hasOwn(input.memory,i)).some(Boolean))throw Error('CANONICAL_EVENT_MEMORY');
 const memory:readonly CanonicalEventAcquisition[]=input.memory;
 for(const a of memory)if(!Array.isArray(a.units)||a.units.length<1||a.units.length>3||typeof a.acquiredAt!=='bigint'||a.acquiredAt<0n||a.acquiredAt>input.now)throw Error('CANONICAL_EVENT_MEMORY');
 const keys=canonicalOperationKeyIndex([...memory.flatMap(a=>a.units.map(u=>u.key)),...input.graph.keys,input.cue.key]);
 const fragments=fragmentRetainedUnits(memory.map(a=>({id:a.id,kind:'EventContinuant',units:a.units.map(u=>({...u,key:keys.label(u.key)}))})),[],{EventContinuant:96,Interoceptive:0}).acquisitions;
 const ids=canonicalOperationKeyIndex(fragments.map(a=>unsigned(a.id))),byId=new Map(memory.map(a=>[a.id,a]));
 const copied=fragments.map(a=>({...a,units:[...a.units].sort((x,y)=>x.key<y.key?-1:1)})).sort((a,b)=>ids.label(unsigned(a.id))<ids.label(unsigned(b.id))?-1:1);
 for(const id of input.presentations.keys())if(!byId.has(id))throw Error('CANONICAL_EVENT_HISTORY');
 const access=composeDirectAssociativeAccess([...new Set(copied.flatMap(a=>a.units.map(u=>u.key)))],input.graph.keys.map(k=>keys.label(k)),input.graph.weights,new Map([[keys.label(input.cue.key),Q.of(1n)]]),p.beta,p.scale);
 const ranked=rankAccessibleEpisodes(copied.map(a=>({key:ids.label(unsigned(a.id)),retainedKeys:a.units.map(u=>u.key),presentations:input.presentations.get(a.id)??[]})),new Map(access.map(a=>[a.key,a.quantized])),input.now,p);
 const idFrom=(label:string)=>{const v=ids.original(label);if(typeof v==='boolean'||v.kind!=='unsigned')throw Error('CANONICAL_EVENT_ID');return v.value;};
 return {disposition:'Evaluated' as const,access:access.map(a=>({...a,key:keys.original(a.key)})),scores:ranked.scored.map(s=>({acquisition:idFrom(s.key),base:s.base,pull:s.pull,score:s.score})),recalled:ranked.selected.map(s=>{const id=idFrom(s.key),a=copied.find(a=>a.id===id)!;return {id,acquiredAt:byId.get(id)!.acquiredAt,units:a.units.map(u=>({key:keys.original(u.key),views:u.views.map(v=>v.slice())}))};})};
}

/** recollection-production/0.1-candidate; PRJ/IDN subject and source/read admission remain upstream. */
import {canonicalEncode,text,typedIdentifier} from '../substrate/canonicalEncoding';
import {recallCanonicalEventAcquisitions,type CanonicalEventRecallInput} from './canonicalEventRecall';
import {recallBodyByAcquisitionRecency,type BodyRecallCue} from './bodyRecall';
export interface RecollectionSubject {readonly observer:string;readonly character:string}
export interface RecollectionView {readonly opaque:'recollection-production-view'}
type EventWinner=ReturnType<typeof recallCanonicalEventAcquisitions>['recalled'][number];
type BodyWinner=ReturnType<typeof recallBodyByAcquisitionRecency>['recalled'][number];
type Content={readonly kind:'EventContinuant';readonly winner:EventWinner}|{readonly kind:'Interoceptive';readonly winner:BodyWinner};
interface Stored {readonly kind:Content['kind'];readonly subject:RecollectionSubject;readonly at:bigint;readonly contents:readonly Content[]}
const views=new WeakMap<object,Stored>();
type PresentationBatch={readonly observer:string;readonly character:string;readonly at:bigint;readonly presentations:readonly {readonly recollection:bigint;readonly acquisition:bigint}[]};
const published=new WeakMap<object,PresentationBatch|null>();
function subjectCopy(subject:RecollectionSubject,at:bigint){
 if(typeof at!=='bigint'||at<0n||typeof subject.observer!=='string'||!subject.observer||typeof subject.character!=='string'||!subject.character)throw Error('RECOLLECTION_SUBJECT');
 canonicalEncode(typedIdentifier(1000,text(subject.observer)));canonicalEncode(typedIdentifier(1002,text(subject.character)));
 return {observer:subject.observer,character:subject.character};
}
function stage(subject:RecollectionSubject,at:bigint,contents:readonly Content[],kind:Content['kind']):RecollectionView{
 const token=Object.freeze({opaque:'recollection-production-view' as const});views.set(token,{kind,subject:{...subject},at,contents:structuredClone(contents)});return token;
}
type EventRead=Pick<CanonicalEventRecallInput,'memory'|'graph'|'presentations'>;
function cueShape(cue:unknown,presentField:string){
 if(!cue||Object.getPrototypeOf(cue)!==Object.prototype)throw Error('RECOLLECTION_CUE');const d=Object.getOwnPropertyDescriptors(cue);
 if(!d.kind||!('value'in d.kind)||!['Absent','Present'].includes(d.kind.value))throw Error('RECOLLECTION_CUE');
 const keys=d.kind.value==='Absent'?['kind']:['kind',presentField];if(Reflect.ownKeys(d).length!==keys.length||keys.some(k=>!d[k]||!('value'in d[k])))throw Error('RECOLLECTION_CUE');
}
export function prepareEventRecollections(subject:RecollectionSubject,cue:CanonicalEventRecallInput['cue'],at:bigint,calibration:CanonicalEventRecallInput['calibration'],read:()=>EventRead){
 const holder=subjectCopy(subject,at);
 cueShape(cue,'key');if(cue.kind==='Present')canonicalEncode(cue.key);
 recallCanonicalEventAcquisitions({cue:{kind:'Absent'},now:at,calibration,memory:[],graph:{keys:[],weights:[]},presentations:new Map()});
 // Unavailable cue still validates the math configuration, without acquiring state.
 const operands=cue.kind==='Absent'?{memory:[],graph:{keys:[],weights:[]},presentations:new Map()}:read();
 const evaluation=recallCanonicalEventAcquisitions({...operands,cue,now:at,calibration});
 return {evaluation,view:stage(holder,at,evaluation.recalled.map(winner=>({kind:'EventContinuant' as const,winner})),'EventContinuant')};
}
export function prepareBodyRecollections(subject:RecollectionSubject,cue:BodyRecallCue,at:bigint,slots:number,read:()=>Parameters<typeof recallBodyByAcquisitionRecency>[0]){
 const holder=subjectCopy(subject,at);cueShape(cue,'signals');
 if(cue.kind==='Present'){if(!Array.isArray(cue.signals)||Object.values(Object.getOwnPropertyDescriptors(cue.signals)).some(d=>!('value'in d)))throw Error('RECOLLECTION_CUE');}
 const empty=recallBodyByAcquisitionRecency([],cue,at,slots),evaluation=cue.kind==='Absent'?empty:recallBodyByAcquisitionRecency(read(),cue,at,slots);
 return {evaluation,view:stage(holder,at,evaluation.recalled.map(winner=>({kind:'Interoceptive' as const,winner})),'Interoceptive')};
}
export function publishRecollections(view:RecollectionView,allocate:()=>bigint){
 const stored=views.get(view);if(!stored)throw Error('RECOLLECTION_VIEW');views.delete(view);
 const seen=new Set<bigint>();
